import numpy as np
import pandas as pd
from datetime import datetime

# Constants
DATE_FORMAT = '%Y-%m-%d %H:%M:%S'


def task_func(result):
    import numbers

    def _is_missing(value):
        if value is None:
            return True
        if value is pd.NA:
            return True
        if isinstance(value, (float, np.floating)):
            return np.isnan(value)
        return False

    def _extract_from_user_values(obj):
        if obj is None:
            return []

        if isinstance(obj, pd.DataFrame):
            if "from_user" not in obj.columns:
                return []
            return obj["from_user"].tolist()

        if isinstance(obj, pd.Series):
            if obj.name == "from_user":
                return obj.tolist()
            if "from_user" in obj.index:
                value = obj["from_user"]
                if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
                    return list(value)
                return [] if _is_missing(value) else [value]
            return []

        if isinstance(obj, dict):
            if "from_user" not in obj:
                return []
            value = obj["from_user"]
            if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
                return list(value)
            return [] if _is_missing(value) else [value]

        try:
            iterator = iter(obj)
        except TypeError:
            return []

        values = []
        for item in iterator:
            if isinstance(item, dict) and "from_user" in item:
                values.append(item["from_user"])
            elif hasattr(item, "from_user"):
                values.append(getattr(item, "from_user"))
        return values

    raw_values = _extract_from_user_values(result)

    cleaned_values = []
    for value in raw_values:
        if _is_missing(value):
            continue
        if isinstance(value, (bool, np.bool_)) or not isinstance(value, numbers.Real):
            raise ValueError('If the "from_user" values are not numeric.')
        cleaned_values.append(float(value))

    current_time = datetime.now().strftime(DATE_FORMAT)

    if not cleaned_values:
        summary = {
            "mean": np.nan,
            "median": np.nan,
            "min": np.nan,
            "max": np.nan,
            "std": np.nan,
            "current_time": current_time,
        }
        return pd.Series(summary)

    arr = np.asarray(cleaned_values, dtype=float)

    summary = {
        "mean": float(np.mean(arr)),
        "median": float(np.median(arr)),
        "min": float(np.min(arr)),
        "max": float(np.max(arr)),
        "std": float(np.std(arr, ddof=1)) if arr.size > 1 else np.nan,
        "current_time": current_time,
    }

    return pd.Series(summary)
